from pathlib import Path
import collections,json,re,urllib.parse
base=Path('docs/agent-work/changeo-implementation/mercadopago-baseline')
files=json.loads(Path('docs/agent-work/changeo-implementation/mercadopago-baseline.json').read_text())['allowed_deliverable_changes']
errors=[]
links=[]
def anchors(p):
 seen=collections.Counter(); result=set()
 for heading in re.findall(r'^#{1,6}\s+(.+)$',p.read_text(),re.M):
  slug=re.sub(r'[^\w\s-]','',heading.strip().lower()).replace(' ','-')
  count=seen[slug]; seen[slug]+=1
  result.add(slug if count==0 else f'{slug}-{count}')
 return result
for rel in files:
 p=Path(rel); content=p.read_text()
 if p.suffix=='.md':
  if sum(bool(re.match(r'^\s*```',line)) for line in content.splitlines())%2: errors.append(rel+':unbalanced fence')
  for target in re.findall(r'\[[^\]]*\]\(([^)]+)\)',content):
   if re.match(r'^[a-z]+://',target): continue
   file,_,fragment=target.partition('#')
   dest=(p.parent/urllib.parse.unquote(file)).resolve() if file else p.resolve()
   ok=dest.is_file() and (not fragment or fragment in anchors(dest))
   links.append({'from':rel,'target':target,'valid':ok})
   if not ok: errors.append(rel+':'+target)
research=Path('docs/gate0-research.md').read_text()
prior=(base/'docs/gate0-research.md').read_text()
oldids=re.findall(r'^\| (G\d{2}\.\d|Y01) \|',prior,re.M)
newids=re.findall(r'^\| (G\d{2}\.\d|Y01) \|',research,re.M)
if oldids!=newids or len(newids)!=25 or len(set(newids))!=25: errors.append('25-ID map changed/lost')
oldr2=prior.split('### Supplied budget and solo support — R2\n',1)[1].split('\n## Already settled requirements',1)[0]
newr2=research.split('### Supplied budget and solo support — R2\n',1)[1].split('\n## Already settled requirements',1)[0]
newr2=newr2.replace('No runtime/trust provider is selected by this comparison; R3 separately selects Mercado Pago for payments.','No new provider is selected.')
if oldr2!=newr2: errors.append('R2 price/support wording changed beyond selection clarification')
checks={}
for rel,heading in [('docs/payments.md','## Agreement and release contract'),('docs/architecture.md','## Core records and behavior contracts'),('docs/business.md','## Subscription behavior')]:
 unchanged=Path(rel).read_text().split(heading,1)[1]==(base/rel).read_text().split(heading,1)[1]
 checks[rel+' from '+heading]=unchanged
 if not unchanged: errors.append('contract/R2 tail changed:'+rel)
for rel in files:
 if 'Mercado Pago' not in Path(rel).read_text(): errors.append('selection absent:'+rel)
for phrase in ['prepared BIND/Mobbex inquiry','reusable-partner-inquiry--prepared-not-sent','Worth a capability inquiry','payment partner, AI vendor']:
 if any(phrase in Path(rel).read_text() for rel in files): errors.append('obsolete current wording:'+phrase)
manifest=json.loads(Path('docs/agent-work/changeo-gate0/developer/mercadopago/logs/sources-manifest.json').read_text())
for entry in manifest['sources']:
 for name in entry['evidence'] if isinstance(entry['evidence'],list) else [entry['evidence']]:
  evidence=Path(name) if name.startswith('docs/') else Path('docs/agent-work/changeo-gate0/developer/mercadopago/logs')/name
  if not evidence.is_file(): errors.append('missing primary log:'+str(evidence))
print(json.dumps({'documents':files,'local_links':links,'local_link_count':len(links),'original_ids':newids,'r2_arithmetic_support_unchanged_except_selection':oldr2==newr2,'contract_tails_unchanged':checks,'primary_manifest_sources':len(manifest['sources']),'errors':errors},indent=2,ensure_ascii=False))
raise SystemExit(1 if errors else 0)
